# dart:_list's WasmListBase (list.dart:15, `int _length` beside `WasmArray<Object?> _data`) is Julia's
# Array{T,1}, laid out by its own fields over its Memory (src/julia/classes.jl `_memory_instance_fields`),
# one class per element type, so no one class answers; its methods are Base's (getindex, length,
# copyto!), compiled as they are (D3). Its one reader, getListBaseArray, is called only from dart's
# Function.apply intrinsic (intrinsics.dart:3381), which no Julia call is, and class_info.dart:126's
# field checks are answered by Array's own fields: no compile reaches it, Internal (A55S14's rule)
@parity "dart2wasm/lib/kernel_nodes.dart:57 KernelNodes.listBaseClass" list_base_class(self::KernelNodes)::Union{} =
    reject!(Internal("dart2wasm/lib/kernel_nodes.dart:57 KernelNodes.listBaseClass: dart:_list's WasmListBase is Julia's Array{T,1}, a class per element type laid out by its own fields, and its one reader, getListBaseArray, is dart's Function.apply intrinsic, which no Julia call is"), "KernelNodes.listBaseClass")

"""
    immutable_list_class(self, element_type) -> DataType

The class of a constant list. dart's is dart:_list's ImmutableList (list.dart:290), one class whose
element type is a type argument, its constant built of WasmListBase's `_length` and `_data`; Julia's
constant list is a `Vector`, an object of its own class `Array{T,1}`, laid out by its own fields (`ref`,
its MemoryRef, and `size`), as `listBaseClass` answers for every list.

Reshaped: `element_type` — Julia's Array{T,1} binds its element type, a class per element type, so the
lookup takes it where dart's one class takes it as a type argument.
"""
@parity "dart2wasm/lib/kernel_nodes.dart:73 KernelNodes.immutableListClass" immutable_list_class(self::KernelNodes, element_type::Type)::DataType =
    Array{element_type,1}

# the lanes of a SIMD vector class, in lane order: dart's _WasmI8x16Impl and its siblings hold them as
# fields `_0`, `_1`, ..., which dart sorts by their number; Julia's SIMD vector is an NTuple of
# VecElement, 16 bytes in all (LLVM's <16 x i8> and its siblings), whose fields are its lanes in
# order, so Julia's field order is the answer and no sort is needed. A lane's reference is its field
# (the Kernel table's Field row: an instance field is a ClassField). Any other class is no SIMD
# vector, which dart's int.parse of a lane name would refuse: it rejects, located
@parity "dart2wasm/lib/kernel_nodes.dart:316 KernelNodes._getLaneReferences" function _get_lane_references(self::KernelNodes, class_node::DataType)::Vector{ClassField}
    local at = "dart2wasm/lib/kernel_nodes.dart:316 KernelNodes._getLaneReferences"
    local ts = fieldtypes(class_node)
    local lanes = class_node <: Tuple && !isempty(ts) && allequal(ts) && ts[1] <: VecElement && sum(sizeof, ts) == 16
    lanes || reject!(Internal("$at: $class_node is no SIMD vector, an NTuple of one VecElement 16 bytes wide"), at)
    return class_instance_fields(class_node, at)
end

